SET @cat = (SELECT id FROM categories WHERE name = 'Fitness');

INSERT IGNORE INTO quest_templates
    (category_id, track, quest_type, title, summary, description, why, difficulty, time_limit_hours)
VALUES
-- Main quests
(@cat,'running','main','Three runs a week for three weeks','Run 5 km or more, nine times in 21 days','Run at least 5 km on three separate days in each of the next three weeks, nine runs in total. Any pace is fine and walking breaks are allowed, but cover the full 5 km each time. Finish the ninth run before the 21 days are up.','Repeating a distance for weeks is what turns a hard effort into an easy one.','hard',504),
(@cat,'mobility','main','Thirty days of stretching','Stretch for 10 minutes on at least 26 of 30 days','Stretch for at least 10 minutes a day, covering your back, hips, legs and shoulders. You may miss up to four days. Tick off each day so you can see the streak build.','Daily flexibility work reduces stiffness and injury risk, and it is easy enough to become a real habit.','medium',720),
(@cat,'strength','main','Add 10 push-ups to your maximum','Raise your best push-up set by 10 in two weeks','Test how many push-ups you can do in one set with good form. Train three times a week, then retest before the 14 days are up. Your new record must beat the first by at least 10.','A clear before-and-after number is the most honest proof that your training works.','hard',336),
(@cat,'walking','main','Walk 8,000 steps for seven days in a row','Hit 8,000 steps every day for a week','Reach at least 8,000 steps on seven consecutive days. If you miss a day, the week starts again. Use a phone or watch to count.','A week of steady movement shows you how much of your day can quietly become exercise.','medium',168),
(@cat,'swimming','main','Swim twice a week for two weeks','Four swims of 20 minutes or more in 14 days','Swim at least 20 minutes on four separate days over the next two weeks, any stroke, resting only briefly. Aim for two swims in each week.','Regular swimming builds whole-body fitness and breathing control without stressing your joints.','medium',336),
(@cat,'running','main','Build up to 10 km in 30 days','Train until you can run 10 km in one go','Plan about three runs a week and slowly increase your longest run until you cover 10 km in a single session. Increase by no more than a kilometre or two each week. The final 10 km must be completed within the 30 days.','Doubling your distance teaches pacing and mental endurance that carry over into everything else.','epic',720),

-- Side quests: running
(@cat,'running','side','Easy 20-minute jog','Jog slowly for 20 minutes','Run at a pace where you could still hold a conversation. Slow is the point.','Easy running builds your aerobic base without wearing your body down.','easy',24),
(@cat,'running','side','Steady 3 km run','Run 3 km at an even pace','Pick a pace you can hold from start to finish and run 3 km without speeding up or stopping.','Even pacing teaches you what a sustainable effort feels like.','medium',24),
(@cat,'running','side','Five fast and slow intervals','Alternate 1 minute fast and 1 minute slow, five times','After a five minute warm-up, run hard for one minute, jog easily for one minute, and repeat five times. Cool down by walking.','Intervals raise your fitness faster than steady running alone.','medium',24),
(@cat,'running','side','Fifteen minutes before breakfast','Run for 15 minutes before you eat','Head out first thing in the morning for an easy 15 minute run before breakfast.','A morning run puts a win on the board before the day can get in the way.','easy',24),
(@cat,'running','side','5 km with a recorded time','Run 5 km and write down your time','Run 5 km at a pace you choose and note the finishing time somewhere you can find it later.','A recorded time gives you something real to beat next time.','medium',48),
(@cat,'running','side','Finish a run with four strides','End an easy run with four 20-second fast bursts','At the end of an easy run, do four relaxed fast runs of about 20 seconds, walking back between each.','Strides improve your running form and leg speed at very little cost.','easy',24),
(@cat,'running','side','Run-walk for 25 minutes','Alternate running and walking for 25 minutes','Run for two minutes, walk for one, and repeat for 25 minutes in total.','Run-walk intervals let beginners build stamina without burning out.','easy',24),

-- Side quests: strength
(@cat,'strength','side','Three sets of ten squats','Do 3 sets of 10 bodyweight squats','Squat with your heels down and chest up, resting for a minute between sets.','Squats train the biggest muscles in your body and support everyday movement.','easy',24),
(@cat,'strength','side','Three sets of eight push-ups','Do 3 sets of 8 push-ups','Do three sets of eight push-ups with a rest between sets. Use your knees if you need to.','Push-ups build the chest, shoulders and arms together.','easy',24),
(@cat,'strength','side','Lunges, three sets of ten per leg','Do 3 sets of 10 lunges on each leg','Step forward into each lunge, keeping your front knee above your ankle and your torso upright.','Lunges expose and fix strength gaps between your left and right sides.','medium',24),
(@cat,'strength','side','Three planks of 45 seconds','Hold a plank for 45 seconds, three times','Hold a straight-body plank for 45 seconds, rest for 30 seconds, and repeat three times.','Short repeated holds build core endurance faster than one painful attempt.','medium',24),
(@cat,'strength','side','Twenty-minute bodyweight circuit','Mix squats, push-ups and planks for 20 minutes','Rotate through squats, push-ups, lunges and planks with little rest for a total of 20 minutes.','You need no equipment for a full workout, which removes the excuse of having no gym.','medium',24),
(@cat,'strength','side','Three sets of fifteen glute bridges','Do 3 sets of 15 glute bridges','Lie on your back with knees bent, lift your hips and squeeze at the top for one second.','Strong glutes protect your lower back and improve how you run and walk.','easy',24),
(@cat,'strength','side','Wall sit, three times','Hold a wall sit for 40 seconds, three times','Slide down a wall until your thighs are level, hold for 40 seconds, rest, and repeat.','Wall sits build leg endurance with almost no impact on your joints.','easy',24),
(@cat,'strength','side','Three sets of twenty calf raises','Do 3 sets of 20 calf raises','Rise onto your toes slowly, pause at the top, and lower with control.','Strong calves protect your ankles and Achilles tendons.','easy',24),
(@cat,'strength','side','Chair dips, three sets of ten','Do 3 sets of 10 triceps dips on a sturdy chair','Lower your body with your hands on the edge of a stable chair, then press back up.','Dips target the back of the arms, which push-ups train less.','medium',24),

-- Side quests: cycling and swimming
(@cat,'cycling','side','Thirty minutes on a bike','Cycle at a comfortable pace for 30 minutes','Ride outdoors or on a stationary bike at a pace where you can still talk.','Cycling builds leg strength and stamina and is gentle on your joints.','easy',24),
(@cat,'cycling','side','Cycle instead of driving','Replace one car or bus trip with a bike ride','Choose one trip you would normally make by car or bus and ride your bike instead.','Turning a normal trip into exercise adds fitness without taking extra time.','easy',48),
(@cat,'cycling','side','Fifteen kilometre ride','Ride about 15 km at a comfortable pace','Plan a route of around 15 km and finish it, stopping for water if needed.','Mid-length rides are where your endurance really starts to grow.','medium',48),
(@cat,'swimming','side','Ten pool lengths','Swim ten lengths at your own pace','Swim ten lengths of the pool in any stroke, resting at the wall when you need to.','Swimming is a full-body workout that is gentle on your joints.','easy',48),
(@cat,'swimming','side','Twenty-five minutes in the pool','Swim for 25 minutes with only short rests','Swim for 25 minutes in total. Short rests are fine, but keep moving.','Time in the water builds breathing control and whole-body endurance.','medium',48),

-- Side quests: mobility
(@cat,'mobility','side','Ten-minute morning stretch','Stretch for 10 minutes after waking','Gently stretch your back, hips, legs and shoulders before starting the day.','Morning stretching reduces stiffness and wakes your body up.','easy',24),
(@cat,'mobility','side','Twenty-minute yoga video','Follow a beginner yoga video','Pick a beginner video of about 20 minutes and follow it through to the end.','Yoga improves flexibility, balance and calm in a single session.','easy',24),
(@cat,'mobility','side','Ten-minute hip opener','Hold hip stretches for 30 to 60 seconds each','Do a series of hip stretches, holding each for 30 to 60 seconds while breathing slowly.','Tight hips cause back and knee problems, especially if you sit a lot.','easy',24),
(@cat,'mobility','side','Foam roll for ten minutes','Roll out your legs and back','Roll slowly over your legs and back, pausing on tender spots for about 20 seconds.','Releasing tension speeds up recovery between workouts.','easy',24),
(@cat,'mobility','side','Shoulder mobility routine','Do arm circles and wall slides for 10 minutes','Do arm circles, wall slides and thread-the-needle stretches for 10 minutes.','Mobile shoulders reduce neck tension and help your posture at a desk.','easy',24),
(@cat,'mobility','side','Two minutes in a deep squat','Rest in a deep squat for two minutes in total','Sit low in a squat, holding on to something if needed, and add up two minutes across as many rounds as you like.','Resting in a deep squat keeps your hips and ankles healthy.','easy',24),

-- Side quests: walking
(@cat,'walking','side','Eight thousand steps','Reach 8,000 steps today','Track your steps with a phone or watch and reach 8,000 before the day ends.','Daily steps are one of the simplest links to better health and mood.','easy',24),
(@cat,'walking','side','Brisk half-hour walk','Walk fast enough to raise your breathing for 30 minutes','Walk at a pace where you breathe a little harder but can still talk, for 30 minutes.','A brisk walk counts as real exercise and clears your head.','easy',24),
(@cat,'walking','side','Ten thousand steps','Reach 10,000 steps today','Reach 10,000 steps before the day ends, spreading them through the day.','The 10,000 mark pushes you to stay active throughout the whole day.','medium',24),
(@cat,'walking','side','Ten-minute walk after a meal','Walk gently after eating','Instead of sitting straight down after a meal, walk for 10 minutes.','A short walk after eating helps digestion and steadies your energy.','easy',24),
(@cat,'walking','side','Walk instead of driving','Go on foot for one errand you would normally drive','Choose a nearby errand, such as the shops or a pickup, and go on foot.','Small trips are the easiest place to hide extra exercise.','easy',48),
(@cat,'walking','side','One-hour walk','Walk for an hour, ideally somewhere green','Go out for a full hour at a relaxed pace, preferably through a park or somewhere quiet.','Long easy time on your feet builds endurance and lowers stress.','medium',48),

-- Side quests: general
(@cat,'general','side','Twenty-minute HIIT workout','Work hard for 40 seconds, rest 20, repeat','Pick four or five moves such as squats, burpees and mountain climbers. Work for 40 seconds, rest for 20, and cycle through for 20 minutes.','High intensity training gives a large fitness boost in a short time.','medium',24),
(@cat,'general','side','Ten minutes of jump rope','Skip for 10 minutes in short rounds','Skip in rounds of one minute with short rests until you have added up ten minutes.','Skipping builds coordination, calves and cardio in very little space.','medium',24),
(@cat,'general','side','Dance for twenty minutes','Put on songs you love and keep moving','Play your favourite songs and dance for 20 minutes without stopping.','Exercise that feels like fun is exercise you will keep doing.','easy',24),
(@cat,'general','side','Thirty burpees','Do 30 burpees, in sets if you like','Spread 30 burpees across the day or do them in sets, resting between.','Burpees work your whole body and show you how fit you really are.','medium',24),
(@cat,'general','side','Play a sport for 45 minutes','Join a game of football, tennis, basketball or similar','Play any sport actively for 45 minutes, with friends or at a local club.','Playing a sport makes training social and competitive in a healthy way.','medium',48),

-- Bonus quests
(@cat,'general','bonus','Try a workout you have never done','Take a class or follow a video in a new style','Pick a style you have never tried, such as boxing, pilates or climbing, and do one session of it.','Trying something new keeps training fresh and may reveal a new favourite.','medium',48),
(@cat,'general','bonus','Train with a friend','Do any workout alongside someone','Invite someone to join you for any workout, in person or on a video call.','Training with someone makes you both more likely to show up.','easy',48),
(@cat,'general','bonus','Take the stairs all day','Skip every lift and escalator today','Use the stairs every time you have a choice, all day.','Stairs are free daily training that adds up quickly.','easy',24),
(@cat,'general','bonus','Work out before 8 in the morning','Finish a session before 8am','Do any workout and finish it before 8 in the morning.','Early exercise makes sure it happens before the day fills up.','easy',24),
(@cat,'mobility','bonus','Stretch every hour at work','Take a two-minute stretch break every hour','Set a reminder and stand up for a two-minute stretch every hour during your working or study day.','Breaking up long sitting protects your back, neck and focus.','easy',24),
(@cat,'running','bonus','Try a new running route','Run somewhere you have never run','Choose a route you have never run before and run it.','A new route turns a familiar run into a small adventure.','easy',48),
(@cat,'running','bonus','Beat your best time on a regular route','Run a familiar route faster than before','Pick a route you know, check your previous time and finish faster.','Racing your past self is the most honest form of progress.','medium',48),
(@cat,'strength','bonus','Learn a new bodyweight exercise','Try one exercise you have never done','Look up an exercise you have not done before, such as pike push-ups, and practise it for a few sets.','New movements challenge your muscles in new ways and prevent plateaus.','easy',24),
(@cat,'strength','bonus','Add one extra set to every exercise','Do one more set of each exercise today','In your next workout add one more set to every exercise you do.','A small extra push is how strength actually grows.','medium',24),
(@cat,'walking','bonus','Walk without headphones','Walk and pay attention to what is around you','Go for a walk with no music or podcasts and notice what you see and hear.','Walking without input lets your mind slow down and settle.','easy',24),
(@cat,'walking','bonus','Sunrise or sunset walk','Time a walk to catch the start or end of the day','Go for a walk around sunrise or sunset and take in the light.','Natural light in the morning or evening supports your sleep and mood.','easy',24),
(@cat,'cycling','bonus','Ride a new route','Explore roads or paths you have never cycled','Choose roads or paths you have never cycled and explore them.','Exploring keeps cycling interesting, so you keep doing it.','easy',48),
(@cat,'swimming','bonus','Try a new swimming stroke','Practise an unfamiliar stroke for a few lengths','Practise a stroke you do not usually swim for at least four lengths.','Learning a new stroke improves technique and uses different muscles.','easy',48),
(@cat,'strength','bonus','Film your form and review it','Record one set from the side and check your posture','Film a set of one exercise from the side and compare your posture with a guide video.','Seeing your form is the quickest way to spot and fix mistakes.','easy',24),
(@cat,'general','bonus','Plan your next week of workouts','Choose days and times and write them down','Choose days and times for the next seven days of exercise and write them in your calendar.','A plan with times attached is far more likely to happen.','easy',24),
(@cat,'mobility','bonus','Cool down with slow breathing','Breathe slowly for five minutes after training','After a workout, sit or lie down and breathe slowly for five minutes.','Cooling down helps your heart rate settle and your body recover.','easy',24);